mapper.select:
SELECT
ADMIN_ID AS adminId,
ADMIN_PWD AS adminPwd
FROM TBL_ADMIN
WHERE ADMIN_ID = #{adminId}
AND ADMIN_PWD = #{adminPwd}

SELECT * FROM ( SELECT 'PRODUCT' AS qnaCategory, '상품 문의' AS qnaCategoryName, Q.QNA_NO AS qnaNo, Q.PRODUCT_NO AS productNo, P.PRODUCT_NAME AS productName, NULL AS unaType, Q.QNA_TITLE AS qnaTitle, Q.Q_CONTENTS AS qContents, Q.A_CONTENTS AS aContents, Q.IS_SECRET AS isSecret, Q.ANS_STATUS AS ansStatus, Q.USER_ID AS userId, Q.CDATE AS cdate, U.USER_NAME AS userName, U.NICKNAME AS nickname FROM QNA Q LEFT JOIN PRODUCT P ON Q.PRODUCT_NO = P.PRODUCT_NO LEFT JOIN USERS U ON Q.USER_ID = U.USER_ID
UNION ALL
SELECT 'HOME' AS qnaCategory, '홈페이지 문의' AS qnaCategoryName, UQ.UNA_NO AS qnaNo, NULL AS productNo, UQ.UNA_TYPE AS productName, UQ.UNA_TYPE AS unaType, UQ.UNA_TITLE AS qnaTitle, UQ.UNA_CONTENT AS qContents, UQ.UNA_ANSWER AS aContents, 'Y' AS isSecret, UQ.ANSWER_YN AS ansStatus, UQ.USER_ID AS userId, UQ.CDATE AS cdate, U.USER_NAME AS userName, U.NICKNAME AS nickname FROM QNA_UNIPET UQ LEFT JOIN USERS U ON UQ.USER_ID = U.USER_ID ) QNA_ALL WHERE 1 = 1
AND ansStatus = #{ansStatus}
AND qnaCategory = #{qnaCategory}
AND qnaCategory = 'HOME' AND unaType = #{unaType}
AND ( productName LIKE CONCAT('%', #{keyword}, '%') OR qnaTitle LIKE CONCAT('%', #{keyword}, '%') OR qContents LIKE CONCAT('%', #{keyword}, '%') OR userId LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY cdate DESC, qnaNo DESC

