choose.when:
SELECT COUNT(*) FROM STORE_SUBMIT SS INNER JOIN STORE S ON SS.STORE_NO = S.STORE_NO INNER JOIN STORE_USER SU ON SS.S_USER_ID = SU.S_USER_ID WHERE SS.SUBMIT_STATUS = 'PND' AND SU.U_STATUS = 'PND' AND S.S_STATUS = 'PND'
AND ( SU.S_USER_ID LIKE CONCAT('%', #{keyword}, '%') OR SU.CEO_NAME LIKE CONCAT('%', #{keyword}, '%') OR S.STORE_NAME LIKE CONCAT('%', #{keyword}, '%') )
AND S.IS_OPEN = #{isOpen}

choose.otherwise:
SELECT COUNT(*) FROM STORE_USER SU INNER JOIN STORE S ON SU.S_USER_ID = S.S_USER_ID WHERE S.S_STATUS != 'EXT'
AND ( SU.S_USER_ID LIKE CONCAT('%', #{keyword}, '%') OR SU.CEO_NAME LIKE CONCAT('%', #{keyword}, '%') OR S.STORE_NAME LIKE CONCAT('%', #{keyword}, '%') )
AND S.S_STATUS = #{sStatus}
AND S.IS_OPEN = #{isOpen}

