mapper.select:
SELECT COUNT(*) FROM PRODUCT P LEFT JOIN PC_ANIMAL_SUB PAS ON P.A_SUB_NO = PAS.A_SUB_NO LEFT JOIN PC_ANIMAL_MAIN PAM ON PAS.A_MAIN_NO = PAM.A_MAIN_NO LEFT JOIN PC_ITEM_SUB PIS ON P.I_SUB_NO = PIS.I_SUB_NO LEFT JOIN PC_ITEM_MAIN PIM ON PIS.I_MAIN_NO = PIM.I_MAIN_NO WHERE 1 = 1
AND ( P.PRODUCT_NAME LIKE CONCAT('%', #{keyword}, '%') OR P.BRAND LIKE CONCAT('%', #{keyword}, '%') )
AND P.PRODUCT_STATUS = #{productStatus}

SELECT P.PRODUCT_NO AS productNo, P.A_SUB_NO AS aSubNo, P.I_SUB_NO AS iSubNo, P.PRODUCT_NAME AS productName, P.BRAND AS brand, P.PRODUCT_PRICE AS productPrice, P.STOCK_QTY AS stockQty, P.PRODUCT_STATUS AS productStatus, P.CDATE AS cdate, PAM.A_MAIN_TYPE AS aMainType, PAS.A_SUB_TYPE AS aSubType, PIM.I_MAIN_TYPE AS iMainType, PIS.I_SUB_TYPE AS iSubType FROM PRODUCT P LEFT JOIN PC_ANIMAL_SUB PAS ON P.A_SUB_NO = PAS.A_SUB_NO LEFT JOIN PC_ANIMAL_MAIN PAM ON PAS.A_MAIN_NO = PAM.A_MAIN_NO LEFT JOIN PC_ITEM_SUB PIS ON P.I_SUB_NO = PIS.I_SUB_NO LEFT JOIN PC_ITEM_MAIN PIM ON PIS.I_MAIN_NO = PIM.I_MAIN_NO WHERE 1 = 1
AND ( P.PRODUCT_NAME LIKE CONCAT('%', #{keyword}, '%') OR P.BRAND LIKE CONCAT('%', #{keyword}, '%') )
AND P.PRODUCT_STATUS = #{productStatus}
ORDER BY P.PRODUCT_NO DESC LIMIT #{startIndex}, #{pageSize}

mapper.update:
UPDATE PRODUCT
SET
    PRODUCT_PRICE = #{productPrice},
    STOCK_QTY = #{stockQty},
    PRODUCT_STATUS = #{productStatus}
WHERE PRODUCT_NO = #{productNo}

UPDATE PRODUCT_FILE
SET FILE_PATH = #{mainImagePath}
WHERE PRODUCT_NO = #{productNo}
  AND IS_MAIN = 'Y'

UPDATE PRODUCT_FILE
SET FILE_PATH = #{detailImagePath}
WHERE PRODUCT_NO = #{productNo}
  AND IS_DETAIL = 'Y'

mapper.select:
SELECT A_SUB_NO AS aSubNo, A_MAIN_NO AS aMainNo, A_SUB_TYPE AS aSubType FROM PC_ANIMAL_SUB WHERE 1 = 1
AND A_MAIN_NO = #{aMainNo}
ORDER BY A_SUB_NO ASC

SELECT I_SUB_NO AS iSubNo, I_MAIN_NO AS iMainNo, I_SUB_TYPE AS iSubType FROM PC_ITEM_SUB WHERE 1 = 1
AND I_MAIN_NO = #{iMainNo}
ORDER BY I_SUB_NO ASC
